"""Stripe integration template — generates services/stripe_client.py."""
from __future__ import annotations


def generate_stripe_client(output_dir=None, config: dict | None = None) -> str:
    """Return production-ready Stripe client code as a string."""
    return '''\
"""Stripe client — generated by AetherOS p04c_integration_codegen."""
from __future__ import annotations
import asyncio
import logging
import os
from functools import partial
from typing import Any, Dict, Optional

logger = logging.getLogger(__name__)


class StripeError(Exception):
    """Base error for Stripe operations."""


class StripeAuthError(StripeError):
    """Raised when Stripe authentication fails."""


class StripeClient:
    """Async Stripe client wrapping the sync stripe SDK via run_in_executor."""

    def __init__(self) -> None:
        import stripe as _stripe
        self._stripe = _stripe
        self._stripe.api_key = os.getenv("STRIPE_SECRET_KEY", "")
        if not self._stripe.api_key:
            logger.warning("STRIPE_SECRET_KEY not set — Stripe calls will fail")

    async def _run(self, fn, *args, **kwargs) -> Any:
        """Run a sync stripe call in a thread pool executor."""
        loop = asyncio.get_event_loop()
        return await loop.run_in_executor(None, partial(fn, *args, **kwargs))

    async def create_customer(self, email: str, name: str = "", metadata: Dict = None) -> Dict:
        """Create a Stripe customer and return the customer object."""
        try:
            return await self._run(
                self._stripe.Customer.create,
                email=email,
                name=name,
                metadata=metadata or {},
            )
        except self._stripe.error.AuthenticationError as exc:
            raise StripeAuthError("Invalid Stripe API key") from exc
        except Exception as exc:
            logger.warning("stripe.create_customer failed: %s", exc)
            raise StripeError(str(exc)) from exc

    async def create_checkout_session(
        self, price_id: str, customer_id: str, success_url: str, cancel_url: str,
        mode: str = "subscription", quantity: int = 1,
    ) -> Dict:
        """Create a Stripe Checkout session and return the session object."""
        try:
            return await self._run(
                self._stripe.checkout.Session.create,
                customer=customer_id,
                payment_method_types=["card"],
                line_items=[{"price": price_id, "quantity": quantity}],
                mode=mode,
                success_url=success_url,
                cancel_url=cancel_url,
            )
        except Exception as exc:
            logger.warning("stripe.create_checkout_session failed: %s", exc)
            raise StripeError(str(exc)) from exc

    async def create_subscription(
        self, customer_id: str, price_id: str, trial_days: int = 0,
    ) -> Dict:
        """Create a subscription for a customer."""
        try:
            params: Dict[str, Any] = {
                "customer": customer_id,
                "items": [{"price": price_id}],
            }
            if trial_days > 0:
                params["trial_period_days"] = trial_days
            return await self._run(self._stripe.Subscription.create, **params)
        except Exception as exc:
            logger.warning("stripe.create_subscription failed: %s", exc)
            raise StripeError(str(exc)) from exc

    async def cancel_subscription(self, subscription_id: str) -> Dict:
        """Cancel a Stripe subscription immediately."""
        try:
            sub = await self._run(self._stripe.Subscription.retrieve, subscription_id)
            return await self._run(sub.delete)
        except Exception as exc:
            logger.warning("stripe.cancel_subscription failed: %s", exc)
            raise StripeError(str(exc)) from exc

    async def get_invoice(self, invoice_id: str) -> Dict:
        """Retrieve a Stripe invoice by ID."""
        try:
            return await self._run(self._stripe.Invoice.retrieve, invoice_id)
        except Exception as exc:
            logger.warning("stripe.get_invoice failed: %s", exc)
            raise StripeError(str(exc)) from exc

    async def handle_webhook(self, payload: bytes, sig_header: str) -> Dict:
        """Verify and parse a Stripe webhook payload."""
        webhook_secret = os.getenv("STRIPE_WEBHOOK_SECRET", "")
        try:
            event = await self._run(
                self._stripe.Webhook.construct_event,
                payload, sig_header, webhook_secret,
            )
            return dict(event)
        except self._stripe.error.SignatureVerificationError as exc:
            logger.warning("stripe.handle_webhook signature invalid: %s", exc)
            raise StripeError("Invalid webhook signature") from exc
        except Exception as exc:
            logger.warning("stripe.handle_webhook failed: %s", exc)
            raise StripeError(str(exc)) from exc


stripe_client = StripeClient()
'''
